    uint8_t oper_type = 0;
    if (off + 1 <= len) { oper_type = body[off]; off += 1; }
    std::string task;
    if (off + 1 <= len) { uint8_t n = body[off]; off += 1; if (off + (size_t)n <= len) { task.assign((const char*)body + off, n); off += n; } }
